#include <atomic>
#if defined(__x86_64__)
#include <immintrin.h>
#define CPU_PAUSE() _mm_pause()
#else
#define CPU_PAUSE() ((void)0)
#endif

class SpinLock {
    std::atomic_flag flag_ = ATOMIC_FLAG_INIT;
public:
    void lock() noexcept {
        while (flag_.test_and_set(std::memory_order_acquire)) {  // acquire on entry
            while (flag_.test(std::memory_order_relaxed))         // C++20: spin read-only
                CPU_PAUSE();                                     // ease contention/power
        }
    }
    void unlock() noexcept { flag_.clear(std::memory_order_release); } // release on exit
};
// acquire(lock)/release(unlock) => writes in the critical section are visible to the next locker.

#include <atomic>
#include <mutex>

// (b) correct ready-flag (message passing)
std::atomic<bool> ready{false};
Data data;
void producer() { data = compute(); ready.store(true, std::memory_order_release); }
void consumer() { while (!ready.load(std::memory_order_acquire)) {} use(data); }

// (c) one-time init
std::once_flag once;
void init_once() { std::call_once(once, []{ /* runs exactly once, thread-safe */ }); }

Config& config() { static Config c = load();  // 'magic static': thread-safe, once
                   return c; }
